 PurchaseInvoiceRef INTEGER REFERENCES PurchaseInvoice(PurchaseInvoiceID),
PurchaseFreightRef INTEGER REFERENCES PurchaseFreight(FreightID),
GoodsReceiptRef INTEGER REFERENCES GoodsReceipt(GoodsReceiptID),
StockTransferRef INTEGER REFERENCES StockTransfer(TransferID),
StockTransferReceiptRef INTEGER REFERENCES StockTransferReceipt(TransferReceiptID),
InventoryAdjustmentRef INTEGER REFERENCES InventoryAdjustment(AdjustmentID),
SalesInvoiceRef INTEGER REFERENCES SalesInvoice(SalesInvoiceID),
SalesReturnRef INTEGER REFERENCES SalesReturn(SalesReturnID),
PurchaseReturnRef INTEGER REFERENCES PurchaseReturn(PurchaseReturnID),
CustomerReceiptRef INTEGER REFERENCES CustomerReceipt(ReceiptID),
SupplierPaymentRef INTEGER REFERENCES SupplierPayment(SupplierPaymentID),
ExpenseRef INTEGER REFERENCES Expense(ExpenseID),
PayrollRef INTEGER REFERENCES Payroll(PayrollID),
SalaryPaymentRef INTEGER REFERENCES SalaryPayment(SalaryPaymentID),
DeliveryRef INTEGER REFERENCES Delivery(DeliveryID),
DeliveryExpenseRef INTEGER REFERENCES DeliveryExpense(DeliveryExpenseID),
FinancialTransferRef INTEGER REFERENCES FinancialTransfer(TransferID),
FixedAssetRef INTEGER REFERENCES FixedAsset(AssetID),
AssetDepreciationRef INTEGER REFERENCES AssetDepreciation(DepreciationID),
AssetDisposalRef INTEGER REFERENCES AssetDisposal(DisposalID),
ExpensePaymentRef INTEGER REFERENCES ExpensePayment(ExpensePaymentID),
ManualJournalRef INTEGER REFERENCES ManualJournal(ManualJournalID), CHECK((PurchaseInvoiceRef IS NOT NULL)+(PurchaseFreightRef IS NOT NULL)+(GoodsReceiptRef IS NOT NULL)+(StockTransferRef IS NOT NULL)+(StockTransferReceiptRef IS NOT NULL)+(InventoryAdjustmentRef IS NOT NULL)+(SalesInvoiceRef IS NOT NULL)+(SalesReturnRef IS NOT NULL)+(PurchaseReturnRef IS NOT NULL)+(CustomerReceiptRef IS NOT NULL)+(SupplierPaymentRef IS NOT NULL)+(ExpenseRef IS NOT NULL)+(PayrollRef IS NOT NULL)+(SalaryPaymentRef IS NOT NULL)+(DeliveryRef IS NOT NULL)+(DeliveryExpenseRef IS NOT NULL)+(FinancialTransferRef IS NOT NULL)+(FixedAssetRef IS NOT NULL)+(AssetDepreciationRef IS NOT NULL)+(AssetDisposalRef IS NOT NULL)+(ExpensePaymentRef IS NOT NULL)+(ManualJournalRef IS NOT NULL)=1), UNIQUE(SourceType,SourceID,SourceEvent)
) STRICT;

