 CHECK((GoodsReceiptDetailRef IS NOT NULL)+(SalesInvoiceDetailRef IS NOT NULL)+(SalesReturnDetailRef IS NOT NULL)+(PurchaseReturnDetailRef IS NOT NULL)+(StockTransferDetailRef IS NOT NULL)+(StockTransferReceiptDetailRef IS NOT NULL)+(InventoryAdjustmentDetailRef IS NOT NULL)=1),
