CREATE TRIGGER Date_InventoryMovement_MovementDate_INSERT BEFORE INSERT ON InventoryMovement WHEN NEW.MovementDate IS NOT NULL AND (length(NEW.MovementDate)<>20 OR strftime('%Y-%m-%dT%H:%M:%SZ',NEW.MovementDate,'+0 seconds') IS NOT NEW.MovementDate) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TRIGGER Date_InventoryMovement_MovementDate_UPDATE BEFORE UPDATE ON InventoryMovement WHEN NEW.MovementDate IS NOT NULL AND (length(NEW.MovementDate)<>20 OR strftime('%Y-%m-%dT%H:%M:%SZ',NEW.MovementDate,'+0 seconds') IS NOT NEW.MovementDate) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TABLE FinancialTransaction (
 TransactionID INTEGER PRIMARY KEY, FinancialAccountID INTEGER NOT NULL REFERENCES FinancialAccount,
 SourceType TEXT NOT NULL, SourceID INTEGER NOT NULL, SourceEvent TEXT NOT NULL,
 TransactionDate TEXT NOT NULL, TransactionType TEXT NOT NULL CHECK(TransactionType IN ('IN','OUT')),
 Amount INTEGER NOT NULL CHECK(Amount>0), Description TEXT NOT NULL, EventID INTEGER NOT NULL REFERENCES PostingEvent,
 UNIQUE(EventID,FinancialAccountID), UNIQUE(SourceType,SourceID,SourceEvent,FinancialAccountID)
) STRICT;

CREATE INDEX IX_FinancialTransaction_FinancialAccountID ON FinancialTransaction(FinancialAccountID);

CREATE INDEX IX_FinancialTransaction_EventID ON FinancialTransaction(EventID);

CREATE TRIGGER Date_FinancialTransaction_TransactionDate_INSERT BEFORE INSERT ON FinancialTransaction WHEN NEW.TransactionDate IS NOT NULL AND (length(NEW.TransactionDate)<>10 OR date(NEW.TransactionDate,'+0 days') IS NOT NEW.TransactionDate) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TRIGGER Date_FinancialTransaction_TransactionDate_UPDATE BEFORE UPDATE ON FinancialTransaction WHEN NEW.TransactionDate IS NOT NULL AND (length(NEW.TransactionDate)<>10 OR date(NEW.TransactionDate,'+0 days') IS NOT NEW.TransactionDate) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TABLE AppUser (
 UserID INTEGER PRIMARY KEY, EmployeeID INTEGER NOT NULL UNIQUE REFERENCES Employee,
 Username TEXT NOT NULL COLLATE NOCASE UNIQUE, PasswordHash TEXT NOT NULL CHECK(length(PasswordHash)>=40 AND
 (PasswordHash GLOB 'scrypt$*' OR PasswordHash GLOB 'pbkdf2_sha256$*' OR PasswordHash GLOB '$argon2id$*' OR PasswordHash GLOB '$2b$*')),
 IsActive INTEGER NOT NULL DEFAULT 1 CHECK(IsActive IN (0,1)), CreatedAt TEXT NOT NULL
) STRICT;

CREATE INDEX IX_AppUser_EmployeeID ON AppUser(EmployeeID);

CREATE TRIGGER Date_AppUser_CreatedAt_INSERT BEFORE INSERT ON AppUser WHEN NEW.CreatedAt IS NOT NULL AND (length(NEW.CreatedAt)<>20 OR strftime('%Y-%m-%dT%H:%M:%SZ',NEW.CreatedAt,'+0 seconds') IS NOT NEW.CreatedAt) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TRIGGER Date_AppUser_CreatedAt_UPDATE BEFORE UPDATE ON AppUser WHEN NEW.CreatedAt IS NOT NULL AND (length(NEW.CreatedAt)<>20 OR strftime('%Y-%m-%dT%H:%M:%SZ',NEW.CreatedAt,'+0 seconds') IS NOT NEW.CreatedAt) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TABLE Role (
 RoleID INTEGER PRIMARY KEY, RoleName TEXT NOT NULL UNIQUE, Description TEXT
) STRICT;

CREATE TABLE UserRole (
 UserID INTEGER NOT NULL REFERENCES AppUser, RoleID INTEGER NOT NULL REFERENCES Role, PRIMARY KEY(UserID,RoleID)
) STRICT;

CREATE INDEX IX_UserRole_UserID ON UserRole(UserID);

CREATE INDEX IX_UserRole_RoleID ON UserRole(RoleID);

CREATE TABLE Permission (
 PermissionID INTEGER PRIMARY KEY, PermissionName TEXT NOT NULL, PermissionCode TEXT NOT NULL UNIQUE, Description TEXT
) STRICT;

CREATE TABLE RolePermission (
 RoleID INTEGER NOT NULL REFERENCES Role, PermissionID INTEGER NOT NULL REFERENCES Permission, PRIMARY KEY(RoleID,PermissionID)
) STRICT;

CREATE INDEX IX_RolePermission_RoleID ON RolePermission(RoleID);

CREATE INDEX IX_RolePermission_PermissionID ON RolePermission(PermissionID);

CREATE TABLE AuditLog (
 AuditLogID INTEGER PRIMARY KEY, UserID INTEGER REFERENCES AppUser, ActionType TEXT NOT NULL,
 EntityName TEXT NOT NULL, AffectedRecordID INTEGER NOT NULL, OldValues TEXT, NewValues TEXT, ActionAt TEXT NOT NULL
) STRICT;

CREATE INDEX IX_AuditLog_UserID ON AuditLog(UserID);

CREATE TRIGGER Date_AuditLog_ActionAt_INSERT BEFORE INSERT ON AuditLog WHEN NEW.ActionAt IS NOT NULL AND (length(NEW.ActionAt)<>20 OR strftime('%Y-%m-%dT%H:%M:%SZ',NEW.ActionAt,'+0 seconds') IS NOT NEW.ActionAt) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

CREATE TRIGGER Date_AuditLog_ActionAt_UPDATE BEFORE UPDATE ON AuditLog WHEN NEW.ActionAt IS NOT NULL AND (length(NEW.ActionAt)<>20 OR strftime('%Y-%m-%dT%H:%M:%SZ',NEW.ActionAt,'+0 seconds') IS NOT NEW.ActionAt) BEGIN SELECT RAISE(ABORT,'invalid ISO date'); END;

