CREATE TRIGGER Freeze_JournalEntryDetail_DELETE BEFORE DELETE ON JournalEntryDetail WHEN (SELECT Status FROM JournalEntry WHERE JournalEntryID=OLD.JournalEntryID)='POSTED' BEGIN SELECT RAISE(ABORT,'posted parent lines are immutable'); END;

CREATE TRIGGER Event_source_INSERT BEFORE INSERT ON PostingEvent WHEN NOT COALESCE(((NEW.SourceType='PurchaseInvoice' AND NEW.SourceID=NEW.PurchaseInvoiceRef) OR (NEW.SourceType='PurchaseFreight' AND NEW.SourceID=NEW.PurchaseFreightRef) OR (NEW.SourceType='GoodsReceipt' AND NEW.SourceID=NEW.GoodsReceiptRef) OR (NEW.SourceType='StockTransfer' AND NEW.SourceID=NEW.StockTransferRef) OR (NEW.SourceType='StockTransferReceipt' AND NEW.SourceID=NEW.StockTransferReceiptRef) OR (NEW.SourceType='InventoryAdjustment' AND NEW.SourceID=NEW.InventoryAdjustmentRef) OR (NEW.SourceType='SalesInvoice' AND NEW.SourceID=NEW.SalesInvoiceRef) OR (NEW.SourceType='SalesReturn' AND NEW.SourceID=NEW.SalesReturnRef) OR (NEW.SourceType='PurchaseReturn' AND NEW.SourceID=NEW.PurchaseReturnRef) OR (NEW.SourceType='CustomerReceipt' AND NEW.SourceID=NEW.CustomerReceiptRef) OR (NEW.SourceType='SupplierPayment' AND NEW.SourceID=NEW.SupplierPaymentRef) OR (NEW.SourceType='Expense' AND NEW.SourceID=NEW.ExpenseRef) OR (NEW.SourceType='Payroll' AND NEW.SourceID=NEW.PayrollRef) OR (NEW.SourceType='SalaryPayment' AND NEW.SourceID=NEW.SalaryPaymentRef) OR (NEW.SourceType='Delivery' AND NEW.SourceID=NEW.DeliveryRef) OR (NEW.SourceType='DeliveryExpense' AND NEW.SourceID=NEW.DeliveryExpenseRef) OR (NEW.SourceType='FinancialTransfer' AND NEW.SourceID=NEW.FinancialTransferRef) OR (NEW.SourceType='FixedAsset' AND NEW.SourceID=NEW.FixedAssetRef) OR (NEW.SourceType='AssetDepreciation' AND NEW.SourceID=NEW.AssetDepreciationRef) OR (NEW.SourceType='AssetDisposal' AND NEW.SourceID=NEW.AssetDisposalRef) OR (NEW.SourceType='ExpensePayment' AND NEW.SourceID=NEW.ExpensePaymentRef) OR (NEW.SourceType='ManualJournal' AND NEW.SourceID=NEW.ManualJournalRef)),0) BEGIN SELECT RAISE(ABORT,'source FK mismatch'); END;

CREATE TRIGGER Event_source_UPDATE BEFORE UPDATE ON PostingEvent WHEN NOT COALESCE(((NEW.SourceType='PurchaseInvoice' AND NEW.SourceID=NEW.PurchaseInvoiceRef) OR (NEW.SourceType='PurchaseFreight' AND NEW.SourceID=NEW.PurchaseFreightRef) OR (NEW.SourceType='GoodsReceipt' AND NEW.SourceID=NEW.GoodsReceiptRef) OR (NEW.SourceType='StockTransfer' AND NEW.SourceID=NEW.StockTransferRef) OR (NEW.SourceType='StockTransferReceipt' AND NEW.SourceID=NEW.StockTransferReceiptRef) OR (NEW.SourceType='InventoryAdjustment' AND NEW.SourceID=NEW.InventoryAdjustmentRef) OR (NEW.SourceType='SalesInvoice' AND NEW.SourceID=NEW.SalesInvoiceRef) OR (NEW.SourceType='SalesReturn' AND NEW.SourceID=NEW.SalesReturnRef) OR (NEW.SourceType='PurchaseReturn' AND NEW.SourceID=NEW.PurchaseReturnRef) OR (NEW.SourceType='CustomerReceipt' AND NEW.SourceID=NEW.CustomerReceiptRef) OR (NEW.SourceType='SupplierPayment' AND NEW.SourceID=NEW.SupplierPaymentRef) OR (NEW.SourceType='Expense' AND NEW.SourceID=NEW.ExpenseRef) OR (NEW.SourceType='Payroll' AND NEW.SourceID=NEW.PayrollRef) OR (NEW.SourceType='SalaryPayment' AND NEW.SourceID=NEW.SalaryPaymentRef) OR (NEW.SourceType='Delivery' AND NEW.SourceID=NEW.DeliveryRef) OR (NEW.SourceType='DeliveryExpense' AND NEW.SourceID=NEW.DeliveryExpenseRef) OR (NEW.SourceType='FinancialTransfer' AND NEW.SourceID=NEW.FinancialTransferRef) OR (NEW.SourceType='FixedAsset' AND NEW.SourceID=NEW.FixedAssetRef) OR (NEW.SourceType='AssetDepreciation' AND NEW.SourceID=NEW.AssetDepreciationRef) OR (NEW.SourceType='AssetDisposal' AND NEW.SourceID=NEW.AssetDisposalRef) OR (NEW.SourceType='ExpensePayment' AND NEW.SourceID=NEW.ExpensePaymentRef) OR (NEW.SourceType='ManualJournal' AND NEW.SourceID=NEW.ManualJournalRef)),0) BEGIN SELECT RAISE(ABORT,'source FK mismatch'); END;

CREATE TRIGGER Source_JournalEntry_INSERT BEFORE INSERT ON JournalEntry WHEN NOT EXISTS(SELECT 1 FROM PostingEvent e WHERE e.EventID=NEW.EventID AND e.Status='PREPARING' AND e.SourceType=NEW.SourceType AND e.SourceID=NEW.SourceID AND e.SourceEvent=NEW.SourceEvent) BEGIN SELECT RAISE(ABORT,'event source mismatch or sealed'); END;

CREATE TRIGGER Source_JournalEntry_UPDATE BEFORE UPDATE ON JournalEntry WHEN NOT EXISTS(SELECT 1 FROM PostingEvent e WHERE e.EventID=NEW.EventID AND e.Status='PREPARING' AND e.SourceType=NEW.SourceType AND e.SourceID=NEW.SourceID AND e.SourceEvent=NEW.SourceEvent) BEGIN SELECT RAISE(ABORT,'event source mismatch or sealed'); END;

CREATE TRIGGER Source_FinancialTransaction_INSERT BEFORE INSERT ON FinancialTransaction WHEN NOT EXISTS(SELECT 1 FROM PostingEvent e WHERE e.EventID=NEW.EventID AND e.Status='PREPARING' AND e.SourceType=NEW.SourceType AND e.SourceID=NEW.SourceID AND e.SourceEvent=NEW.SourceEvent) BEGIN SELECT RAISE(ABORT,'event source mismatch or sealed'); END;

CREATE TRIGGER Source_FinancialTransaction_UPDATE BEFORE UPDATE ON FinancialTransaction WHEN NOT EXISTS(SELECT 1 FROM PostingEvent e WHERE e.EventID=NEW.EventID AND e.Status='PREPARING' AND e.SourceType=NEW.SourceType AND e.SourceID=NEW.SourceID AND e.SourceEvent=NEW.SourceEvent) BEGIN SELECT RAISE(ABORT,'event source mismatch or sealed'); END;

CREATE TRIGGER Open_StockAllocation BEFORE INSERT ON StockAllocation WHEN (SELECT Status FROM PostingEvent WHERE EventID=NEW.EventID)<>'PREPARING' BEGIN SELECT RAISE(ABORT,'event is sealed'); END;

CREATE TRIGGER Open_InventoryMovement BEFORE INSERT ON InventoryMovement WHEN (SELECT Status FROM PostingEvent WHERE EventID=NEW.EventID)<>'PREPARING' BEGIN SELECT RAISE(ABORT,'event is sealed'); END;

CREATE TRIGGER Journal_balance BEFORE UPDATE OF Status ON JournalEntry WHEN NEW.Status='POSTED' AND ((SELECT count(*) FROM JournalEntryDetail WHERE JournalEntryID=NEW.JournalEntryID)<2 OR (SELECT COALESCE(sum(Debit),0) FROM JournalEntryDetail WHERE JournalEntryID=NEW.JournalEntryID)<=0 OR (SELECT COALESCE(sum(Debit-Credit),0) FROM JournalEntryDetail WHERE JournalEntryID=NEW.JournalEntryID)<>0) BEGIN SELECT RAISE(ABORT,'unbalanced journal'); END;

CREATE TRIGGER Journal_period BEFORE UPDATE OF Status ON JournalEntry WHEN NEW.Status='POSTED' AND NOT EXISTS(SELECT 1 FROM AccountingPeriod p JOIN FinancialYear y USING(FinancialYearID) WHERE p.AccountingPeriodID=NEW.AccountingPeriodID AND y.FinancialYearID=NEW.FinancialYearID AND p.Status='OPEN' AND y.Status='OPEN' AND NEW.EntryDate BETWEEN p.StartDate AND p.EndDate AND NEW.EntryDate BETWEEN y.StartDate AND y.EndDate) BEGIN SELECT RAISE(ABORT,'closed or mismatched period'); END;

CREATE TRIGGER Journal_accounts BEFORE UPDATE OF Status ON JournalEntry WHEN NEW.Status='POSTED' AND EXISTS(SELECT 1 FROM JournalEntryDetail d JOIN ChartOfAccounts a USING(AccountID) WHERE d.JournalEntryID=NEW.JournalEntryID AND a.IsPostingAllowed<>1) BEGIN SELECT RAISE(ABORT,'account does not allow posting'); END;

CREATE TRIGGER Event_seal BEFORE UPDATE OF Status ON PostingEvent WHEN NEW.Status='POSTED' AND ((NEW.HasFinancialEffect=1 AND NOT EXISTS(SELECT 1 FROM JournalEntry j WHERE j.EventID=NEW.EventID AND j.Status='POSTED')) OR (NEW.HasFinancialEffect=0 AND EXISTS(SELECT 1 FROM JournalEntry j WHERE j.EventID=NEW.EventID)) OR EXISTS(SELECT 1 FROM StockAllocation a WHERE a.EventID=NEW.EventID AND NOT EXISTS(SELECT 1 FROM InventoryMovement m WHERE m.StockAllocationID=a.StockAllocationID))) BEGIN SELECT RAISE(ABORT,'incomplete posting event'); END;

CREATE TRIGGER Approval_PurchaseInvoice BEFORE UPDATE OF Status ON PurchaseInvoice WHEN NEW.Status='POSTED' AND NOT EXISTS(SELECT 1 FROM PostingEvent e WHERE e.SourceType='PurchaseInvoice' AND e.SourceID=NEW.PurchaseInvoiceID AND e.SourceEvent='POST' AND e.Status='POSTED') BEGIN SELECT RAISE(ABORT,'post through accounting service'); END;

