CREATE TRIGGER Allocation_source BEFORE INSERT ON StockAllocation WHEN NOT ((NEW.GoodsReceiptDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM GoodsReceiptDetail d JOIN PostingEvent e ON e.SourceID=d.GoodsReceiptID AND e.SourceType='GoodsReceipt' WHERE d.GoodsReceiptDetailID=NEW.GoodsReceiptDetailRef AND e.EventID=NEW.EventID)) OR (NEW.SalesInvoiceDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM SalesInvoiceDetail d JOIN PostingEvent e ON e.SourceID=d.SalesInvoiceID AND e.SourceType='SalesInvoice' WHERE d.SalesInvoiceDetailID=NEW.SalesInvoiceDetailRef AND e.EventID=NEW.EventID)) OR (NEW.SalesReturnDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM SalesReturnDetail d JOIN PostingEvent e ON e.SourceID=d.SalesReturnID AND e.SourceType='SalesReturn' WHERE d.SalesReturnDetailID=NEW.SalesReturnDetailRef AND e.EventID=NEW.EventID)) OR (NEW.PurchaseReturnDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM PurchaseReturnDetail d JOIN PostingEvent e ON e.SourceID=d.PurchaseReturnID AND e.SourceType='PurchaseReturn' WHERE d.PurchaseReturnDetailID=NEW.PurchaseReturnDetailRef AND e.EventID=NEW.EventID)) OR (NEW.StockTransferDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM StockTransferDetail d JOIN PostingEvent e ON e.SourceID=d.TransferID AND e.SourceType='StockTransfer' WHERE d.TransferDetailID=NEW.StockTransferDetailRef AND e.EventID=NEW.EventID)) OR (NEW.StockTransferReceiptDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM StockTransferReceiptDetail d JOIN PostingEvent e ON e.SourceID=d.TransferReceiptID AND e.SourceType='StockTransferReceipt' WHERE d.TransferReceiptDetailID=NEW.StockTransferReceiptDetailRef AND e.EventID=NEW.EventID)) OR (NEW.InventoryAdjustmentDetailRef IS NOT NULL AND EXISTS(SELECT 1 FROM InventoryAdjustmentDetail d JOIN PostingEvent e ON e.SourceID=d.AdjustmentID AND e.SourceType='InventoryAdjustment' WHERE d.AdjustmentDetailID=NEW.InventoryAdjustmentDetailRef AND e.EventID=NEW.EventID))) BEGIN SELECT RAISE(ABORT,'allocation source mismatch'); END;

CREATE TRIGGER Movement_allocation BEFORE INSERT ON InventoryMovement WHEN NOT EXISTS(SELECT 1 FROM StockAllocation a JOIN InventoryBatch b USING(BatchID) JOIN PostingEvent e USING(EventID) WHERE a.StockAllocationID=NEW.StockAllocationID AND a.EventID=NEW.EventID AND a.BatchID=NEW.BatchID AND a.WarehouseID=NEW.WarehouseID AND a.Quantity=NEW.Quantity AND a.CostAmount=NEW.CostAmount AND b.ProductID=NEW.ProductID AND e.SourceType=NEW.SourceType AND NEW.SourceDetailID=COALESCE(a.GoodsReceiptDetailRef,a.SalesInvoiceDetailRef,a.SalesReturnDetailRef,a.PurchaseReturnDetailRef,a.StockTransferDetailRef,a.StockTransferReceiptDetailRef,a.InventoryAdjustmentDetailRef)) BEGIN SELECT RAISE(ABORT,'movement allocation mismatch'); END;

CREATE TRIGGER Movement_stock BEFORE INSERT ON InventoryMovement WHEN NEW.Quantity<0 AND NOT EXISTS(SELECT 1 FROM BatchStock WHERE WarehouseID=NEW.WarehouseID AND BatchID=NEW.BatchID AND CurrentQuantity>=-NEW.Quantity AND CostAmount>=-NEW.CostAmount) BEGIN SELECT RAISE(ABORT,'insufficient batch stock'); END;

CREATE TRIGGER Apply_movement AFTER INSERT ON InventoryMovement BEGIN
      INSERT INTO BatchStock(WarehouseID,BatchID,CurrentQuantity,CostAmount)
      SELECT NEW.WarehouseID,NEW.BatchID,NEW.Quantity,NEW.CostAmount WHERE NEW.Quantity>0
      ON CONFLICT(WarehouseID,BatchID) DO UPDATE SET CurrentQuantity=CurrentQuantity+excluded.CurrentQuantity,CostAmount=CostAmount+excluded.CostAmount;
      UPDATE BatchStock SET CurrentQuantity=CurrentQuantity+NEW.Quantity,CostAmount=CostAmount+NEW.CostAmount
      WHERE WarehouseID=NEW.WarehouseID AND BatchID=NEW.BatchID AND NEW.Quantity<0;
      INSERT INTO InventoryBalance(WarehouseID,ProductID,CurrentQuantity)
      SELECT NEW.WarehouseID,NEW.ProductID,NEW.Quantity WHERE NEW.Quantity>0
      ON CONFLICT(WarehouseID,ProductID) DO UPDATE SET CurrentQuantity=CurrentQuantity+excluded.CurrentQuantity;
      UPDATE InventoryBalance SET CurrentQuantity=CurrentQuantity+NEW.Quantity
      WHERE WarehouseID=NEW.WarehouseID AND ProductID=NEW.ProductID AND NEW.Quantity<0;
    END;

CREATE TRIGGER Ownership_GoodsReceiptDetail_INSERT BEFORE INSERT ON GoodsReceiptDetail WHEN (SELECT PurchaseInvoiceID FROM GoodsReceipt WHERE GoodsReceiptID=NEW.GoodsReceiptID) IS NOT (SELECT PurchaseInvoiceID FROM PurchaseInvoiceDetail WHERE PurchaseInvoiceDetailID=NEW.PurchaseInvoiceDetailID) BEGIN SELECT RAISE(ABORT,'document ownership mismatch'); END;

