CREATE TRIGGER Period_range_INSERT BEFORE INSERT ON AccountingPeriod WHEN NOT EXISTS(SELECT 1 FROM FinancialYear y WHERE y.FinancialYearID=NEW.FinancialYearID AND NEW.StartDate>=y.StartDate AND NEW.EndDate<=y.EndDate) OR EXISTS(SELECT 1 FROM AccountingPeriod p WHERE p.AccountingPeriodID<>NEW.AccountingPeriodID AND p.StartDate<=NEW.EndDate AND p.EndDate>=NEW.StartDate) BEGIN SELECT RAISE(ABORT,'period overlap or year mismatch'); END;

CREATE TRIGGER Year_range_INSERT BEFORE INSERT ON FinancialYear WHEN EXISTS(SELECT 1 FROM FinancialYear y WHERE y.FinancialYearID<>NEW.FinancialYearID AND y.StartDate<=NEW.EndDate AND y.EndDate>=NEW.StartDate) BEGIN SELECT RAISE(ABORT,'financial years overlap'); END;

CREATE TRIGGER Period_range_UPDATE BEFORE UPDATE ON AccountingPeriod WHEN NOT EXISTS(SELECT 1 FROM FinancialYear y WHERE y.FinancialYearID=NEW.FinancialYearID AND NEW.StartDate>=y.StartDate AND NEW.EndDate<=y.EndDate) OR EXISTS(SELECT 1 FROM AccountingPeriod p WHERE p.AccountingPeriodID<>NEW.AccountingPeriodID AND p.StartDate<=NEW.EndDate AND p.EndDate>=NEW.StartDate) BEGIN SELECT RAISE(ABORT,'period overlap or year mismatch'); END;

CREATE TRIGGER Year_range_UPDATE BEFORE UPDATE ON FinancialYear WHEN EXISTS(SELECT 1 FROM FinancialYear y WHERE y.FinancialYearID<>NEW.FinancialYearID AND y.StartDate<=NEW.EndDate AND y.EndDate>=NEW.StartDate) BEGIN SELECT RAISE(ABORT,'financial years overlap'); END;

CREATE TRIGGER Historical_FinancialYear BEFORE UPDATE OF StartDate,EndDate ON FinancialYear WHEN EXISTS(SELECT 1 FROM AccountingPeriod WHERE FinancialYearID=OLD.FinancialYearID) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Historical_AccountingPeriod BEFORE UPDATE OF StartDate,EndDate,FinancialYearID ON AccountingPeriod WHEN EXISTS(SELECT 1 FROM JournalEntry WHERE AccountingPeriodID=OLD.AccountingPeriodID) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Historical_FinancialAccount BEFORE UPDATE OF PostingAccountID ON FinancialAccount WHEN EXISTS(SELECT 1 FROM FinancialTransaction WHERE FinancialAccountID=OLD.FinancialAccountID) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Historical_SystemSetting BEFORE UPDATE OF MoneyScale,QuantityScale,CurrencyName ON SystemSetting WHEN EXISTS(SELECT 1 FROM PostingEvent) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Historical_AccountingPolicy BEFORE UPDATE OF InventoryAccountID,ClearingAccountID,ReceivableAccountID,PayableAccountID,RevenueAccountID,CostOfSalesAccountID,ExpenseAccountID,PayrollExpenseAccountID,PayrollPayableAccountID,ExpensePayableAccountID,TransitAccountID,AdjustmentAccountID,DepreciationExpenseAccountID,AccumulatedDepreciationAccountID,DisposalGainAccountID,DisposalLossAccountID ON AccountingPolicy WHEN EXISTS(SELECT 1 FROM PostingEvent) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Keep_SystemSetting BEFORE DELETE ON SystemSetting WHEN EXISTS(SELECT 1 FROM PostingEvent) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Keep_AccountingPolicy BEFORE DELETE ON AccountingPolicy WHEN EXISTS(SELECT 1 FROM PostingEvent) BEGIN SELECT RAISE(ABORT,'historical configuration is immutable'); END;

CREATE TRIGGER Historical_account_type BEFORE UPDATE OF AccountType,ParentAccountID ON ChartOfAccounts WHEN EXISTS(SELECT 1 FROM JournalEntryDetail d JOIN JournalEntry j USING(JournalEntryID) WHERE d.AccountID=OLD.AccountID AND j.Status='POSTED') BEGIN SELECT RAISE(ABORT,'historical account classification is immutable'); END;

CREATE TRIGGER Account_cycle_INSERT BEFORE INSERT ON ChartOfAccounts WHEN NEW.ParentAccountID IS NOT NULL AND EXISTS(WITH RECURSIVE ancestors(AccountID,ParentAccountID) AS (
                SELECT AccountID,ParentAccountID FROM ChartOfAccounts WHERE AccountID=NEW.ParentAccountID
                UNION SELECT a.AccountID,a.ParentAccountID FROM ChartOfAccounts a JOIN ancestors p ON a.AccountID=p.ParentAccountID)
                SELECT 1 FROM ancestors WHERE AccountID=NEW.AccountID) BEGIN SELECT RAISE(ABORT,'account hierarchy cycle'); END;

CREATE TRIGGER Account_cycle_UPDATE BEFORE UPDATE ON ChartOfAccounts WHEN NEW.ParentAccountID IS NOT NULL AND EXISTS(WITH RECURSIVE ancestors(AccountID,ParentAccountID) AS (
                SELECT AccountID,ParentAccountID FROM ChartOfAccounts WHERE AccountID=NEW.ParentAccountID
                UNION SELECT a.AccountID,a.ParentAccountID FROM ChartOfAccounts a JOIN ancestors p ON a.AccountID=p.ParentAccountID)
                SELECT 1 FROM ancestors WHERE AccountID=NEW.AccountID) BEGIN SELECT RAISE(ABORT,'account hierarchy cycle'); END;

CREATE INDEX IX_JournalEntry_Date_Status ON JournalEntry(EntryDate,Status);

CREATE INDEX IX_PostingEvent_Source_Status ON PostingEvent(SourceType,SourceID,Status);

CREATE VIEW StockInTransit AS SELECT d.TransferDetailID,d.TransferID,d.ProductID,d.Quantity ShippedQuantity,
          d.Quantity-COALESCE((SELECT sum(r.ReceivedQuantity) FROM StockTransferReceiptDetail r
            JOIN StockTransferReceipt h USING(TransferReceiptID) WHERE r.TransferDetailID=d.TransferDetailID AND h.Status='POSTED'),0) RemainingQuantity
          FROM StockTransferDetail d JOIN StockTransfer t USING(TransferID) WHERE t.Status='POSTED';

